/* Whether two operand-index lists name the same set. */
static int same_operand_set(const int8_t *a, int na, const int *b, int nb) {
  int i, j;
  if (na != nb) return 0;
  for (i = 0; i < na; i++) {
    for (j = 0; j < nb; j++)
      if (a[i] == b[j]) break;
    if (j == nb) return 0;
  }
  return 1;
}

void e2_roles_check(void) {
  int r, missing = 0, mismatch = 0;

  for (r = 1; r < ROP_COUNT; r++) {
    const E2Role *role = e2_roles[r];

    if (role == NULL) {
      fprintf(stderr, "e2_roles: no entry for ROP %d\n", r);
      missing++;
      continue;
    }
    /* The format in the table was produced from the engine's own
       `regvm_rop_fmt` by gen-roles.py; a stale table is caught there, where the
       engine is visible. Here only the table's own consistency is checked. */
    if (role->fmt == NULL || role->fmt[0] == 0) {
      fprintf(stderr, "e2_roles: ROP %d: no format\n", r);
      mismatch++;
    }
    if (role->ndef > 2 || role->nuse > 8) {
      fprintf(stderr, "e2_roles: ROP %d: operand counts out of range\n", r);
      mismatch++;
      continue;
    }
    /* Where the IR models an op, its operand roles and the table's must be the
       same sets. The lowerings read operands through the table, so a
       disagreement is a miscompile: `put_field` once listed its receiver as a
       destination, and the store lowering took the value for the receiver. */
    {
      const Q2RopInfo *ri = q2_rop_info((uint16_t)r);
      if (ri->op != Q2_OP_FALLBACK &&
          (!same_operand_set(role->def, role->ndef, ri->def, ri->ndef) ||
           !same_operand_set(role->use, role->nuse, ri->use, ri->nuse))) {
        fprintf(stderr, "e2_roles: ROP %d: operand roles differ from the IR's\n",
                r);
        mismatch++;
      }
    }
  }
  if (missing || mismatch) {
    fprintf(stderr, "e2_roles: %d missing, %d inconsistent; run gen-roles.py\n",
            missing, mismatch);
    abort();
  }
}


void e2_rop_name(uint16_t rop, char *out, size_t n)
{
  snprintf(out, n, "%s", e2_names[rop < ROP_COUNT ? rop : 0]);
}

